"""Render a local HTML review from the checked mass and packing data."""
from pathlib import Path
import json,html
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[3]
def main():
    options=json.loads((HERE/'options.json').read_text(encoding="utf-8"))['variants'];packing=json.loads((HERE/'packing.json').read_text(encoding="utf-8"))['variants'];baseline=json.loads((HERE/'mass-budget.json').read_text(encoding="utf-8"));session=json.loads((HERE/'session.json').read_text(encoding="utf-8"));cards=[];rows=[]
    def e(s):return html.escape(str(s))
    def fmt(m):return f'{m[1]:.2f} g <small>({m[0]:.2f}–{m[2]:.2f})</small>'
    for v,p in zip(options,packing):
        L,W=v['controller_mm'];HL,HW=v['head_mm'];FL,FW=v['free_flex_mm'];hx=L+FL;bits=[]
        def rect(x,y,w,h,cls,tip):bits.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" class="{cls}"><title>{e(tip)}</title></rect>')
        rect(0,0,L,W,'board','Controller outline');rect(hx,(W-HW)/2,HL,HW,'board','Camera head outline');rect(L,(W-FW)/2,FL,FW,'flex','Free inter-board flex: included in module mass');rect(-8,.25,8,7.8,'exit','Mating / tether exit space; cable mass excluded')
        for c in p['parts']:
            x,y,w,h=c['rect_mm'];bx,by=(0,0) if c['board']=='controller' else (hx,(W-HW)/2);side=c['source_side'];rect(bx+x,by+y,w,h,'component side'+side,c['reference']+' '+c['value']+' — '+c['assumption'])
            if c['reference'] in ['U101','U102','U1','J101','J102']:
                bits.append(f'<text class="ref side{side}" x="{bx+x+w/2}" y="{by+y+h/2+.4}">{c["reference"]}</text>')
        if v['id']=='C':
            rect(7.8,W/2-5,10,10,'stiff sideB','P4 underside stiffener reservation')
            x=hx+HL/2-4;y=W/2-4
            for a,b,w,h in [(x,y,8,.75),(x,y+7.25,8,.75),(x,y+.75,.75,6.5),(x+7.25,y+.75,.75,6.5)]:rect(a,b,w,h,'stiff sideB','Lens support stiffener ring; strength unqualified')
        cx=hx+HL/2;cy=W/2;rect(cx-4,cy-4,8,8,'holder sideF','8 x 8 mm support footprint')
        bits.append(f'<circle class="lens sideF" cx="{cx}" cy="{cy}" r="3"><title>6 mm lens envelope; IR close focus unqualified</title></circle>')
        rect(.25,W-2.45,7.2,2.2,'pad sideB','Programming pads, reserved but unrouted')
        bits.append(f'<path class="dimension" d="M0 {W+2} H{hx+HL} M0 {W+1.3} V{W+2.7} M{hx+HL} {W+1.3} V{W+2.7}"/>')
        bits.append(f'<text class="dimtext" x="{(hx+HL)/2}" y="{W+5}">{hx+HL:.2f} mm flat span · {FL:.2f} × {FW} mm free flex</text>')
        svg=f'<svg viewBox="-10 -2 100 26" role="img" aria-label="Candidate {v["id"]} checked courtyard packing">'+''.join(bits)+'</svg>'
        (HERE/f'candidate-{v["id"]}.svg').write_text(svg.replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" ',1).replace('>','><style>.board{fill:#b6ded8;stroke:#287e74;stroke-width:.13}.flex{fill:#edc66d}.component{fill:#354957;stroke:white;stroke-width:.07}.ref{fill:white;text-anchor:middle;font-size:1.05px}.holder{fill:#9055a055;stroke:#754188;stroke-width:.15}.lens{fill:#2c7996}.exit{fill:none;stroke:#7c9aab;stroke-width:.15;stroke-dasharray:.6 .5}.sideB{display:none}.dimtext{font-size:1.5px;text-anchor:middle}.dimension{fill:none;stroke:#647787;stroke-width:.12}</style>',1),encoding="utf-8")
        cards.append(f'<section class="card"><div class="cardhead"><h2>{v["id"]} · {e(v["name"])}</h2><b>{fmt(v["mass_g"]["total"])}</b></div><p>{L} × {W} mm controller · {HL} × {HW} mm head · board {v["rigid_thickness_mm"]:.3f} mm / flex {v["flex_thickness_mm"]:.3f} mm</p>{svg}<p class="caption">{e(v["construction"])}</p></section>')
        m=v['mass_g'];rows.append(f'<tr><th>{v["id"]}</th><td>{fmt(m["total"])}</td><td>{m["boards"][1]:.3f}</td><td>{m["components"][1]:.3f}</td><td>{m["optics"][1]:.3f}</td><td>{m["solder_adhesive_retention"][1]:.3f}</td></tr>')
    checklist=''.join('<li>'+('☑' if t['complete'] else '☐')+' '+e(t['text'])+'</li>' for t in session['tasks'])
    doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OV9281 — size and mass comparison</title>
<style>body{margin:0;background:#f0f3f6;color:#192839;font:16px/1.5 "Segoe UI",sans-serif}main{max-width:1100px;margin:auto;padding:32px 24px 64px}h1{font-size:35px;line-height:1.15;margin:8px 0 16px}h2{font-size:22px;margin:0}h3{font-size:18px}p{margin:10px 0}a{color:#17628a}.tag{font-size:13px;font-weight:700;color:#32657a;text-transform:uppercase;letter-spacing:.08em}.summary,.card{background:white;border:1px solid #d6e0e7;border-radius:12px;padding:22px;margin:20px 0}.summary{border-left:5px solid #30857a}.notice{background:#fff1d8;padding:13px 17px;border-radius:8px}.cardhead{display:flex;justify-content:space-between;gap:16px;align-items:baseline}.caption,small{font-size:13px;color:#526676;font-weight:400}svg{width:100%;background:#fbfcfd;margin:12px 0}.board{fill:#b6ded8;stroke:#287e74;stroke-width:.13}.flex{fill:#edc66d;stroke:#a57b23;stroke-width:.12}.exit{fill:none;stroke:#7c9aab;stroke-dasharray:.6 .5;stroke-width:.15}.component{fill:#354957;stroke:white;stroke-width:.07}.ref{fill:white;text-anchor:middle;font-size:1.05px;pointer-events:none}.holder{fill:#9055a055;stroke:#754188;stroke-width:.15}.lens{fill:#2c7996;stroke:#19364b;stroke-width:.15}.stiff{fill:#c8b28b;stroke:#82734f;stroke-width:.15}.pad{fill:#daa747;stroke:#896f25;stroke-width:.12}.dimension{stroke:#647787;stroke-width:.12;fill:none}.dimtext{font-size:1.5px;text-anchor:middle;fill:#344c5b}.sideB{display:none}body.bottom .sideB{display:initial}body.bottom .sideF{display:none}button{font:inherit;background:white;border:1px solid #8098a9;border-radius:6px;padding:8px 18px;cursor:pointer}button.active{color:white;background:#225e76}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #dce4ea;font-size:14px}.wide{overflow:auto}.native{width:100%;border:1px solid #dbe4ea;background:white}.checklist{list-style:none;padding:0}.checklist li{padding:5px 0;font-size:14px}code{font-size:12px;overflow-wrap:anywhere}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:750px){.cardhead{display:block}.columns{display:block}main{padding:20px 12px}h1{font-size:28px}}</style>
<main><div class="tag">OV9281 + ESP32-P4 · packaging study R01</div><h1>Smaller, lighter — with the mass accounted for.</h1><p>The target is <b>less than 1.000 g for the complete module, excluding the external tether</b>. The sensor head, controller, inter-board flex, optics, illuminators, board-side connector and retention stay inside that total.</p>
<section class="summary"><p class="notice"><b>Selected direction: C — SLIM.flex.</b> The user chose the better-documented construction on 2026-10-28. Its small size increase is acceptable. <a href="../selection-r01/DECISION.md">Decision record</a>. The original comparison below remains evidence; B is no longer the preferred direction.</p><h2>The result</h2><p>The aggressive layout fits a <b>24 × 12 mm controller and 12 × 12 mm camera head</b>. Its estimated nominal mass is <b>1.10 g</b>. The construction based on a published thin-flex stackup, with separate local stiffeners, needs <b>26 × 12.5 mm / 12.5 × 12.5 mm</b> and estimates <b>1.27 g</b>.</p><p class="notice"><b>The subgram target is still open.</b> Low scenarios are below one gram, but neither nominal design meets it. These are unbuilt packaging studies, not newly routed or functional cameras.</p><p>R10 estimates 2.18–3.92 g (nominal 2.95 g). The Pupil model's controller is 30.85 × 9 mm, head 15 × 6 mm and free ribbon 32.85 × 4 mm. Its ~0.7 g mass is user-reported; the weighing boundary is not confirmed. Printed model volumes are not camera mass.</p></section>
<h2>Checked component packing</h2><p>These drawings use the same coordinates as the new FreeCAD model. Dark rectangles are component courtyard reservations. Hover over them for reference IDs and replacement assumptions. Purple outlines reserve the lens support. A keeps existing package types; B/C require qualified smaller replacements.</p><p><button id="front" class="active" onclick="side(false)">Front / optics</button> <button id="back" onclick="side(true)">Underside / supports</button> <small>Underside uses the same coordinate frame, not a mirrored fabrication view.</small></p>
'''+''.join(cards)+'''
<section class="card"><h2>What contributes to the estimate?</h2><p>All values below are grams, with the tether excluded. Low/high values are engineering scenarios, not measured confidence bounds. Courtyard prism volumes are never used as package mass.</p><div class="wide"><table><thead><tr><th>Option</th><th>Total: nominal (range)</th><th>Boards</th><th>Packages</th><th>Optics</th><th>Solder / retention</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p>Dominant gains: smaller board area and qualified thinner copper; integrated flex without J102; smaller flash/regulator packages; a lighter hollow holder. Preserve electrical return paths. Do not simply remove ground copper to save weight.</p></section>
<section class="card"><h2>The native work</h2><p>The FreeCAD comparison contains the selected complete Pupil R08 model, the preserved R10 geometry, and all three proposed packings. The native source is saved as <code>generated/ov9281-size-mass-r01/OV9281-SIZE-MASS-R01.FCStd</code>.</p><img class="native" src="../../../../generated/ov9281-size-mass-r01/comparison-top.png" alt="Native FreeCAD top view with five dimensioned comparison rows"><details><summary>Native underside view: C above, B below</summary><p class="caption">C has the beige support plate and ring; B has no separate underside stiffeners.</p><img class="native" src="../../../../generated/ov9281-size-mass-r01/compact-bottom.png" alt="Native underside view showing components and local stiffeners"></details></section>
<div class="columns"><section class="card"><h2>Checked here</h2><p>106 package reservations in A; 105 in B/C after removing J102. Board containment, same-side non-overlap, sensor/filter/lens clearances, local stiffener clearance, connector exit reservation, valid CAD shapes and saved-file integrity.</p><p>R10 electrical files and the selected Pupil checkpoint remain unchanged.</p></section><section class="card"><h2>Still to qualify</h2><p>Replacement parts and real weights; a manufacturable stackup and new routing; 10–20 mm IR focus; holder threads and strength; illumination, power and temperature; USB behavior; cable construction and physical testing.</p><p>The 8 mm ribbon is a space reservation, not a demonstrated routed interconnect. The new holder's axial overlap drops to 0.47 mm with 1 mm lens extension; thread retention is not established.</p></section></div>
<section class="card"><h2>Recommendation and cost</h2><p>Proceed with C as the selected development direction. Resolve actual component choices, weights and construction constraints before rerouting. A is useful as a lower-complexity comparison, but it misses the lightweight target substantially.</p><p>No supplier quote has been obtained. Compare equal assembled quantities and separate tooling, fabrication, assembly, parts, inspection, yield and shipping. A is expected to be least disruptive; B/C require premium fabrication and assembly. No vendor has been contacted.</p><p><a href="RECOMMENDATION.md">Original study recommendation</a> · <a href="component-budget.csv">Package budget CSV</a> · <a href="options.json">Construction assumptions</a> · <a href="packing.json">Checked placements</a> · <a href="tether-budget.json">Separate tether budget</a> · <a href="geometry-validation.json">CAD checks</a></p><p class="caption">Primary construction source: <a href="https://www.we-online.com/files/pdf1/en_flex6_6f_030_12_2v13.pdf">Würth SLIM.flex stackup</a>. Component-region / neck dimensions are a published template, not project approval. Additional evidence and review scopes are recorded in OPTIONS.md and the repository bibliography.</p></section>
<section class="card"><h2>Approved five-item session</h2><ul class="checklist">'''+checklist+'''</ul></section></main><script>function side(bottom){document.body.classList.toggle('bottom',bottom);document.getElementById('front').classList.toggle('active',!bottom);document.getElementById('back').classList.toggle('active',bottom)}</script></html>'''
    (HERE/'index.html').write_text(doc,encoding='utf-8');print('Rendered index.html and three coordinate-derived SVGs')
if __name__=='__main__':main()
